apps = {"appA": 70, "appB": 50, "appC": 40}
cluster = 100

def fifo(apps):
    res = {a: 0 for a in apps}
    free = cluster
    for a in ["appA", "appB", "appC"]:
        give = min(apps[a], free)
        res[a] = give
        free -= give
    return res

def capacity(apps):
    res = {}
    q1cap, q2cap = 50, 50
    a = min(apps["appA"], q1cap); res["appA"] = a; rem1 = q1cap - a
    b = min(apps["appB"], rem1); res["appB"] = b
    c = min(apps["appC"], q2cap); res["appC"] = c
    return res

def fair(apps):
    res = {a: 0 for a in apps}
    free = cluster
    order = list(apps.keys())
    while free > 0:
        progress = False
        for a in order:
            if res[a] < apps[a] and free > 0:
                res[a] += 1
                free -= 1
                progress = True
        if not progress:
            break
    return res

for name, fn in [("FIFO", fifo), ("Capacity", capacity), ("Fair", fair)]:
    r = fn(apps)
    print(f"{name}: {r}  total={sum(r.values())}")
